fn split_scheme(url: &str) -> Option<(&str, &str)> {
    let idx = url.find("://")?;
    let scheme = url.get(..idx)?;
    let rest = url.get(idx + 3..)?;
    if scheme.is_empty() || rest.is_empty() {
        return None;
    }
    Some((scheme, rest))
}

/// Split an authority from the remainder of a URL.
///
/// An authority ends at the first `/`, `?` or `#` (RFC 3986). Splitting on `/`
/// alone made `h.example?tenant=x` an authority — which produced a "host"
/// carrying a query in [`canonical_resource`], and a metadata URL with the query
/// spliced in front of the well-known path in [`resource_metadata_url`]. The
/// remainder keeps its delimiter, so a caller can tell a path from a query.
fn split_authority(rest: &str) -> (&str, &str) {
    match rest.find(['/', '?', '#']) {
        Some(i) => (rest.get(..i).unwrap_or(rest), rest.get(i..).unwrap_or("")),
        None => (rest, ""),
    }
}

/// The canonical resource identifier for an MCP server (RFC 8707).
///
/// Lowercases the scheme and the **host**, and nothing else:
///
/// * the **path** is preserved exactly, because paths are case-sensitive — `/MCP`
///   and `/mcp` are different resources, and folding them would let a token
///   minted for one be selected for the other;
/// * the **port** is preserved and validated as digits;
/// * **userinfo is refused outright.** Credentials do not identify a resource, and
///   lowercasing them would silently corrupt a case-sensitive password. Accepting
///   them would also mean binding a token to an identifier that embeds a secret.
///
/// A fragment makes the value invalid rather than being stripped, since silently
/// dropping part of an identifier changes which resource is named.
pub fn canonical_resource(url: &str) -> Option<String> {
    if url
        .bytes()
        .any(|b| b.is_ascii_control() || b.is_ascii_whitespace() || matches!(b, b'#' | b'\\' | b'"'))
    {
        return None;
    }
    let (scheme, rest) = split_scheme(url)?;
    if !scheme.eq_ignore_ascii_case("https") && !scheme.eq_ignore_ascii_case("http") {
        return None;
    }
    let (authority, path) = split_authority(rest);
    if authority.is_empty() || authority.contains('@') {
        return None;
    }

    // Structurally strict host/port split. Anything ambiguous is REFUSED rather
    // than normalised: an identifier with two possible spellings is not
    // canonical, and canonical identity is what the credential key rests on.
    let (host, port) = if let Some(after_open) = authority.strip_prefix('[') {
        // A bracketed literal: exactly one closing bracket, then nothing or :port.
        let close = after_open.find(']')?;
        let inner = after_open.get(..close)?;
        if inner.is_empty()
            || !inner.contains(':')
            || !inner
                .bytes()
                .all(|b| b.is_ascii_hexdigit() || matches!(b, b':' | b'.'))
        {
            return None;
        }
        // `strip_prefix` returning None is what refuses `[::1]evil` — anything
        // after the bracket that is not a port makes the authority malformed.
        let port = match after_open.get(close + 1..)? {
            "" => None,
            tail => Some(tail.strip_prefix(':')?),
        };
        // The brackets are part of the host's canonical form.
        (authority.get(..close + 2)?, port)
    } else {
        // No brackets, and at most one colon (the port delimiter). An UNBRACKETED
        // IPv6 literal has several and is refused: RFC 3986 requires the
        // brackets, and accepting it would give one address two spellings.
        if authority.contains('[') || authority.contains(']') {
            return None;
        }
        let mut parts = authority.split(':');
        let host = parts.next()?;
        let port = parts.next();
        if parts.next().is_some() {
            return None;
        }
        if host.is_empty()
            || host.starts_with('.')
            || host.contains("..")
            || !host
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_'))
        {
            return None;
        }
        (host, port)
    };
    if host.is_empty() {
        return None;
    }

    let mut out = String::new();
    out.push_str(&scheme.to_ascii_lowercase());
    out.push_str("://");
    out.push_str(&host.to_ascii_lowercase());
    if let Some(p) = port {
        // A non-numeric, zero, or out-of-range port is malformed, not something to normalise.
        if p.is_empty()
            || !p.bytes().all(|b| b.is_ascii_digit())
            || !p.parse::<u16>().is_ok_and(|n| n != 0)
        {
            return None;
        }
        out.push(':');
        out.push_str(p);
    }
    if !path.is_empty() && path != "/" {
        out.push_str(path);
    }
    Some(out)
}

/// The PKCE method. `plain` is deliberately not offered.
pub const CODE_CHALLENGE_METHOD: &str = "S256";

const LABEL_VERIFIER: &[u8] = b"mcp/pkce-verifier/v1";
const LABEL_STATE: &[u8] = b"mcp/oauth-state/v1";

/// Derive a PKCE `code_verifier` under an injected secret.
///
/// A constrained app has no RNG, so this is HMAC rather than randomness:
/// unguessable to anyone without `secret`, and **deterministic**, which is what a
/// redelivered request needs. A fresh random verifier on a retry would orphan the
/// authorization already in flight, and the user would be walked through the
/// consent screen twice for one connection.
///
/// `attempt` lets a deliberate re-authorization (a step-up, or a user
/// reconnecting) derive a different verifier rather than reuse one whose code may
/// already have been redeemed.
pub fn derive_verifier(secret: &[u8], connection: &str, attempt: u32) -> String {
    let mac = hmac_sha256_concat(
        secret,
        &[
            LABEL_VERIFIER,
            connection.as_bytes(),
            &attempt.to_be_bytes(),
        ],
    );
    b64::encode_url(&mac)
}

/// Derive the OAuth `state` for the same connection.
///
/// A distinct label keeps state and verifier from colliding even though both come
/// from the same secret and connection.
pub fn derive_state(secret: &[u8], connection: &str, attempt: u32) -> String {
    let mac = hmac_sha256_concat(
        secret,
        &[LABEL_STATE, connection.as_bytes(), &attempt.to_be_bytes()],
    );
    b64::encode_url(&mac)
}

/// `code_challenge` for a verifier: unpadded `base64url(SHA256(verifier))`.
pub fn code_challenge(verifier: &str) -> String {
    b64::encode_url(&sha256(verifier.as_bytes()))
}

/// Percent-encode for a query component, escaping everything outside the
/// unreserved set.
///
/// Deliberately strict: `+` must not survive as a space, and an `&` or `=` inside
/// a scope or a state value would otherwise forge a parameter.
pub(crate) fn q(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for b in value.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(hex_digit(b >> 4));
                out.push(hex_digit(b & 0x0f));
            }
        }
    }
    out
}

fn hex_digit(nibble: u8) -> char {
    match nibble {
        0..=9 => (b'0' + nibble) as char,
        _ => (b'A' + (nibble - 10)) as char,
    }
}

/// Everything needed to send a user to an authorization server.
#[derive(Debug, Clone)]
pub struct AuthorizeRequest<'a> {
    pub metadata: &'a AuthServerMetadata,
    pub client_id: &'a str,
    pub redirect_uri: &'a str,
    /// The scopes to request. Empty omits the parameter, which is what the
    /// specification prescribes when neither a challenge nor `scopes_supported`
    /// offered any.
    pub scopes: &'a [String],
    /// The canonical resource URI (RFC 8707). Mandatory.
    pub resource: &'a str,
    pub state: &'a str,
    pub code_challenge: &'a str,
}

/// Build the authorization URL.
///
/// The parameters are placed in the endpoint's query, never after a fragment:
/// a fragment is not sent to the server, so parameters appended behind one
/// would silently vanish. Any fragment is dropped (RFC 6749 §3.1 forbids one
/// on this endpoint), and any parameter the endpoint already names that this
/// function also sends is dropped from the endpoint's query, so no parameter
/// is ever sent twice. [`parse_as_metadata`] refuses both shapes up front;
/// this keeps a hand-built [`AuthServerMetadata`] from producing them.
pub fn authorize_url(req: &AuthorizeRequest<'_>) -> String {
    let endpoint = req.metadata.authorization_endpoint.as_str();
    let endpoint = endpoint.split('#').next().unwrap_or(endpoint);
    let (base, existing) = endpoint.split_once('?').unwrap_or((endpoint, ""));
    let mut url = String::from(base);
    url.push('?');
    for pair in existing.split('&').filter(|pair| !pair.is_empty()) {
        let name = percent_decode(pair.split('=').next().unwrap_or(""));
        if AUTHORIZE_PARAMS.contains(&name.as_str()) {
            continue;
        }
        url.push_str(pair);
        url.push('&');
    }
    url.push_str("response_type=code");
    url.push_str("&client_id=");
    url.push_str(&q(req.client_id));
    url.push_str("&redirect_uri=");
    url.push_str(&q(req.redirect_uri));
    url.push_str("&state=");
    url.push_str(&q(req.state));
    url.push_str("&code_challenge=");
    url.push_str(&q(req.code_challenge));
    url.push_str("&code_challenge_method=");
    url.push_str(CODE_CHALLENGE_METHOD);
    // MUST be sent whether or not the AS advertises support for it.
    url.push_str("&resource=");
    url.push_str(&q(req.resource));
    if !req.scopes.is_empty() {
        url.push_str("&scope=");
        url.push_str(&q(&req.scopes.join(" ")));
    }
    url
}

/// Choose the scopes for an initial authorization, in the specified priority.
///
/// A `WWW-Authenticate` challenge is authoritative when present: the
/// specification says a client MUST treat it so, and MUST NOT assume any set
/// relationship between it and `scopes_supported`. Only without a challenge does
/// the resource's advertised set apply, and when neither exists the parameter is
/// omitted rather than guessed.
pub fn initial_scopes(challenge: &[String], resource_scopes: &[String]) -> Vec<String> {
    if !challenge.is_empty() {
        return challenge.to_vec();
    }
    resource_scopes.to_vec()
}

/// The scope set for a step-up: the UNION of what was requested before and what
/// this challenge demands, order-stable and de-duplicated.
///
/// Requesting only the challenged scopes would silently drop permissions the
/// client already depends on, so a step-up for one tool would break another.
pub fn step_up_scopes(previously_requested: &[String], challenged: &[String]) -> Vec<String> {
    let mut out: Vec<String> = Vec::with_capacity(previously_requested.len() + challenged.len());
    for s in previously_requested.iter().chain(challenged.iter()) {
        if !out.iter().any(|existing| existing == s) {
            out.push(s.clone());
        }
    }
    out
}

/// The outcome of RFC 9207 issuer validation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum IssuerCheck {
    /// Safe to redeem the authorization code.
    Ok,
    /// Refuse. Nothing from the response may be acted on **or displayed** — an
    /// `error_description` from an unverified issuer is attacker-supplied text.
    Reject(&'static str),
}

/// Validate the `iss` parameter of an authorization response (RFC 9207).
///
/// `recorded` is the issuer taken from metadata [`parse_as_metadata`]
/// validated against the issuer it was requested for, stored beside the PKCE
/// verifier. The check is worthless if it came from anywhere else.
///
/// | metadata advertises `iss` | `iss` in response | action |
/// | --- | --- | --- |
/// | yes | present | compare |
/// | yes | absent | **reject** |
/// | no | present | compare |
/// | no | absent | proceed |
///
/// The comparison is byte-exact simple string comparison. **No normalisation of
/// any kind**: no scheme or host case folding, no default-port elision, no
/// trailing-slash or percent-encoding cleanup. Any of those would make a hostile
/// issuer compare equal to the recorded one, which is precisely the mix-up attack
/// this parameter exists to prevent.
pub fn validate_issuer(
    recorded: &str,
    response_iss: Option<&str>,
    advertised: bool,
) -> IssuerCheck {
    match (advertised, response_iss) {
        (_, Some(iss)) => {
            if iss == recorded {
                IssuerCheck::Ok
            } else {
                IssuerCheck::Reject("authorization response iss does not match the recorded issuer")
            }
        }
        (true, None) => IssuerCheck::Reject(
            "authorization server advertises iss support but the response omitted it",
        ),
        (false, None) => IssuerCheck::Ok,
    }
}

/// The form body for redeeming an authorization code.
///
/// `resource` is included per RFC 8707 and is not optional: it is what binds the
/// issued token to one resource server.
pub fn token_request_form(
    code: &str,
    redirect_uri: &str,
    client_id: &str,
    verifier: &str,
    resource: &str,
) -> String {
    let mut f = String::from("grant_type=authorization_code");
    f.push_str("&code=");
    f.push_str(&q(code));
    f.push_str("&redirect_uri=");
    f.push_str(&q(redirect_uri));
    f.push_str("&client_id=");
    f.push_str(&q(client_id));
    f.push_str("&code_verifier=");
    f.push_str(&q(verifier));
    f.push_str("&resource=");
    f.push_str(&q(resource));
    f
}

/// The form body for a refresh. `resource` rides here too — a refresh that omitted
/// it could be answered with a token for a different audience.
pub fn refresh_request_form(refresh_token: &str, client_id: &str, resource: &str) -> String {
    let mut f = String::from("grant_type=refresh_token");
    f.push_str("&refresh_token=");
    f.push_str(&q(refresh_token));
    f.push_str("&client_id=");
    f.push_str(&q(client_id));
    f.push_str("&resource=");
    f.push_str(&q(resource));
    f
}

/// A successful token response.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TokenGrant {
    pub access_token: String,
    pub refresh_token: Option<String>,
    /// Seconds, when the AS committed to one.
    pub expires_in: Option<u64>,
    /// The scopes actually GRANTED, which may differ from those requested. This
    /// is what a later step-up unions against.
    pub scope: Vec<String>,
}

/// Parse a token response.
///
/// Requires what OAuth 2.1 §5.1 requires: a non-empty `access_token` **and** a
/// `token_type`, which must be Bearer. `token_type` is not optional — a token
/// whose type was never stated is a token the client has not established how to
/// use, and guessing Bearer would be the client inventing the server's answer.
///
/// There is deliberately **no audience check**: token responses need not carry an
/// audience, an opaque token has none to inspect, and an unverified JWT's claims
/// are attacker-controlled. Audience binding comes from having SENT `resource`,
/// and is enforced by the resource server on the other side.
pub fn parse_token_response(doc: &Value) -> Result<TokenGrant, &'static str> {
    let access_token = doc
        .get("access_token")
        .and_then(Value::as_str)
        .filter(|s| !s.is_empty())
        .ok_or("token response carried no access_token")?;
    let kind = doc
        .get("token_type")
        .and_then(Value::as_str)
        .filter(|s| !s.is_empty())
        .ok_or("token response carried no token_type, which OAuth 2.1 requires")?;
    if !kind.eq_ignore_ascii_case("bearer") {
        return Err("token response declared a non-bearer token_type");
    }
    Ok(TokenGrant {
        access_token: access_token.to_string(),
        refresh_token: doc
            .get("refresh_token")
            .and_then(Value::as_str)
            .filter(|s| !s.is_empty())
            .map(str::to_string),
        expires_in: doc.get("expires_in").and_then(Value::as_u64),
        scope: doc
            .get("scope")
            .and_then(Value::as_str)
            .map(|s| s.split_whitespace().map(str::to_string).collect())
            .unwrap_or_default(),
    })
}

/// A parsed Bearer challenge.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Challenge {
    pub error: Option<String>,
    pub error_description: Option<String>,
    pub scope: Vec<String>,
    /// The `resource_metadata` URI, which is how a 401 tells a client where to
    /// begin discovery.
    pub resource_metadata: Option<String>,
}

impl Challenge {
    /// Does this challenge say the token was fine but under-scoped?
    pub fn is_insufficient_scope(&self) -> bool {
        self.error.as_deref() == Some("insufficient_scope")
    }
}

/// Parse a `WWW-Authenticate` header value.
///
/// Tolerates the shapes servers actually emit: any capitalisation of the scheme,
/// quoted or bare values, whitespace around separators. An unrecognised parameter
/// is ignored rather than failing the parse — a server may add its own, and
/// refusing the whole challenge would discard the scope guidance that makes
/// step-up work.
pub fn parse_challenge(header: &str) -> Option<Challenge> {
    let rest = header.trim();
    let (scheme, params) = match rest.find(char::is_whitespace) {
        Some(i) => (rest.get(..i)?, rest.get(i + 1..)?),
        None => (rest, ""),
    };
    if !scheme.eq_ignore_ascii_case("bearer") {
        return None;
    }
    let mut out = Challenge::default();
    let mut seen: Vec<String> = Vec::new();
    // An unclosed quoted-string is malformed, not something to guess at.
    for part in split_params(params)? {
        let Some(eq) = part.find('=') else { continue };
        let name = part.get(..eq)?.trim().to_ascii_lowercase();
        let value = unquote(part.get(eq + 1..)?.trim());
        if matches!(name.as_str(), "error" | "error_description" | "scope" | "resource_metadata") {
            // RFC 6750 §3: each attribute MUST NOT appear more than once. A
            // repeat is a smuggling shape (which one did the server mean?).
            if seen.contains(&name) {
                return None;
            }
            seen.push(name.clone());
        }
        match name.as_str() {
            "error" => out.error = Some(value),
            "error_description" => out.error_description = Some(value),
            "scope" => out.scope = value.split_whitespace().map(str::to_string).collect(),
            // Discovery GETs this URL, so it must be an https URL; anything
            // else (plain http, file:, a link-local host spelled oddly) is
            // dropped and the client derives the well-known location itself.
            "resource_metadata" => {
                out.resource_metadata = is_https_url(&value).then_some(value);
            }
            _ => {}
        }
    }
    Some(out)
}

/// A parameter value without its quotes, with quoted-pair escapes undone.
fn unquote(raw: &str) -> String {
    let Some(inner) = raw.strip_prefix('"').and_then(|r| r.strip_suffix('"')) else {
        return raw.to_string();
    };
    let mut out = String::with_capacity(inner.len());
    let mut chars = inner.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(next) = chars.next() {
                out.push(next);
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Split on commas that are not inside a quoted value.
///
/// A naive split breaks a quoted scope list and, worse, truncates an
/// `error_description` containing a comma — losing exactly the text a person needs
/// when authorization fails.
///
/// A backslash inside a quoted value escapes the next character (RFC 9110
/// quoted-pair), so `\"` does not end the value. `None` when a quoted value
/// is never closed.
fn split_params(input: &str) -> Option<Vec<&str>> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut quoted = false;
    let mut escaped = false;
    for (i, c) in input.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        match c {
            '\\' if quoted => escaped = true,
            '"' => quoted = !quoted,
            ',' if !quoted => {
                if let Some(s) = input.get(start..i) {
                    out.push(s);
                }
                start = i + 1;
            }
            _ => {}
        }
    }
    if quoted {
        return None;
    }
    if let Some(s) = input.get(start..) {
        if !s.trim().is_empty() {
            out.push(s);
        }
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use ferrite_app::serde_json;

    const SECRET: &[u8] = b"an injected app secret";

    fn as_meta(iss_supported: bool) -> AuthServerMetadata {
        AuthServerMetadata {
            issuer: "https://as.example.com".into(),
            authorization_endpoint: "https://as.example.com/authorize".into(),
            token_endpoint: "https://as.example.com/token".into(),
            registration_endpoint: None,
            scopes_supported: vec!["mcp:read".into()],
            code_challenge_methods_supported: vec!["S256".into()],
            iss_parameter_supported: iss_supported,
        }
    }

    #[test]
    fn protected_resource_metadata_needs_a_resource_and_an_as() {
        let good = serde_json::json!({
            "resource": "https://h.example/mcp",
            "authorization_servers": ["https://as.example.com"],
            "scopes_supported": ["mcp:read", "mcp:write"]
        });
        let m = parse_resource_metadata(&good, "https://h.example/mcp").expect("valid");
        assert_eq!(m.resource, "https://h.example/mcp");
        assert_eq!(m.scopes_supported.len(), 2);

        // No authorization server means nowhere to obtain a token.
        let no_as = serde_json::json!({ "resource": "https://h.example/mcp", "authorization_servers": [] });
        assert!(parse_resource_metadata(&no_as, "https://h.example/mcp").is_none());
        // No resource means nothing to bind a token to.
        let no_resource = serde_json::json!({ "authorization_servers": ["https://as.example.com"] });
        assert!(parse_resource_metadata(&no_resource, "https://h.example/mcp").is_none());
    }

    /// F189: RFC 9728 §3.3. A PRM naming a resource other than the server it
    /// was fetched for is refused, so a connector cannot choose the token
    /// audience or the credential key.
    #[test]
    fn protected_resource_metadata_must_name_the_server_it_was_fetched_for() {
        let prm = |resource: &str| {
            serde_json::json!({
                "resource": resource,
                "authorization_servers": ["https://as.example.com"]
            })
        };
        let expected = "https://h.example/mcp";
        assert!(parse_resource_metadata(&prm("https://someone-else.example/mcp"), expected).is_none());
        assert!(parse_resource_metadata(&prm("https://h.example/other"), expected).is_none());
        // Paths are case-sensitive, so /MCP is a different resource.
        assert!(parse_resource_metadata(&prm("https://h.example/MCP"), expected).is_none());
        assert!(parse_resource_metadata(&prm("not a url"), expected).is_none());
        assert!(parse_resource_metadata(&prm("https://h.example/mcp"), "not a url").is_none());
        // RFC 9728 §3.3 requires the identical identifier: a spelling that
        // only normalises to the same resource is refused too.
        assert!(parse_resource_metadata(&prm("HTTPS://H.Example/mcp"), expected).is_none());
        assert!(parse_resource_metadata(&prm("https://h.example/mcp/"), expected).is_none());
        assert!(parse_resource_metadata(&prm("https://h.example:443/mcp"), expected).is_none());
        let same = parse_resource_metadata(&prm(expected), expected).expect("same resource");
        assert_eq!(same.resource, expected);
    }

    /// F189: authorization servers must be `https://`. Others are dropped, and
    /// a document left with none is refused.
    #[test]
    fn only_https_authorization_servers_survive_parsing() {
        let mixed = serde_json::json!({
            "resource": "https://h.example/mcp",
            "authorization_servers": [
                "http://as.example.com",
                "file:///etc/passwd",
                "https://user@as.example.com",
                "https://as.example.com"
            ]
        });
        let m = parse_resource_metadata(&mixed, "https://h.example/mcp").expect("one usable AS");
        assert_eq!(m.authorization_servers, vec!["https://as.example.com".to_string()]);

        let none_usable = serde_json::json!({
            "resource": "https://h.example/mcp",
            "authorization_servers": ["http://as.example.com", "gopher://as.example.com"]
        });
        assert!(parse_resource_metadata(&none_usable, "https://h.example/mcp").is_none());
    }

    #[test]
    fn the_prm_url_puts_well_known_at_the_root_and_appends_the_path() {
        assert_eq!(
            resource_metadata_url("https://h.example/mcp").as_deref(),
            Some("https://h.example/.well-known/oauth-protected-resource/mcp")
        );
        assert_eq!(
            resource_metadata_url("https://h.example").as_deref(),
            Some("https://h.example/.well-known/oauth-protected-resource")
        );
        assert_eq!(
            resource_metadata_url("https://h.example/").as_deref(),
            Some("https://h.example/.well-known/oauth-protected-resource")
        );
    }

    #[test]
    fn a_resources_query_is_not_part_of_its_metadata_location() {
        // A query is accepted in a resource identifier, and RFC 9728 locates the
        // document by PATH. Carrying the query through would have a client request
        // one address while a server routing on its own derivation expected
        // another — so such a deployment could publish nowhere reachable.
        let with_query = "https://h.example/mcp?tenant=x";
        assert_eq!(
            canonical_resource(with_query).as_deref(),
            Some(with_query),
            "the identifier itself keeps its query"
        );
        assert_eq!(
            resource_metadata_url(with_query).as_deref(),
            Some("https://h.example/.well-known/oauth-protected-resource/mcp"),
            "but its metadata location does not"
        );
        // A bare query with no path is still the root form.
        assert_eq!(
            resource_metadata_url("https://h.example/?a=b").as_deref(),
            Some("https://h.example/.well-known/oauth-protected-resource")
        );
    }

    #[test]
    fn an_authority_ends_before_a_query_even_with_no_slash() {
        // `h.example?tenant=x` is not an authority. Treating it as one put a query
        // inside a host and spliced it in front of the well-known path.
        assert_eq!(
            resource_metadata_url("https://h.example?tenant=x").as_deref(),
            Some("https://h.example/.well-known/oauth-protected-resource")
        );
        // The identifier keeps the query; the HOST is just the host, lowercased.
        assert_eq!(
            canonical_resource("https://H.Example?tenant=x").as_deref(),
            Some("https://h.example?tenant=x")
        );
        // And a port is still found, rather than swallowed by the query.
        assert_eq!(
            canonical_resource("https://H.Example:8443?a=b").as_deref(),
            Some("https://h.example:8443?a=b")
        );
    }

    #[test]
    fn an_issuer_with_a_query_or_fragment_yields_no_discovery_urls() {
        // RFC 8414 §2: an issuer identifier MUST NOT carry either. Appending the
        // remainder as a path produced `…?x=1/.well-known/openid-configuration`,
        // with the discovery suffix inside a query — an address nothing serves.
        assert!(as_metadata_urls("https://as.example?x=1").is_empty());
        assert!(as_metadata_urls("https://as.example/tenant?x=1").is_empty());
        assert!(as_metadata_urls("https://as.example#frag").is_empty());
    }

    #[test]
    fn both_as_discovery_forms_are_offered_and_they_differ() {
        // The point: RFC 8414 INSERTS the segment, OIDC APPENDS it. An AS with a
        // tenant path is only reachable if both are tried.
        let urls = as_metadata_urls("https://as.example.com/tenant1");
        assert_eq!(
            urls,
            vec![
                "https://as.example.com/.well-known/oauth-authorization-server/tenant1".to_string(),
                "https://as.example.com/tenant1/.well-known/openid-configuration".to_string(),
            ]
        );
        let urls = as_metadata_urls("https://as.example.com");
        assert_eq!(
            urls[0],
            "https://as.example.com/.well-known/oauth-authorization-server"
        );
        assert_eq!(
            urls[1],
            "https://as.example.com/.well-known/openid-configuration"
        );
    }

    #[test]
    fn as_metadata_requires_the_endpoints_a_code_flow_needs() {
        let full = serde_json::json!({
            "issuer": "https://as.example.com",
            "authorization_endpoint": "https://as.example.com/authorize",
            "token_endpoint": "https://as.example.com/token",
            "authorization_response_iss_parameter_supported": true
        });
        assert!(
            parse_as_metadata(&full, "https://as.example.com")
                .expect("valid")
                .iss_parameter_supported
        );

        // Absent means false, not unknown-therefore-lenient.
        let quiet = serde_json::json!({
            "issuer": "https://as.example.com",
            "authorization_endpoint": "https://a",
            "token_endpoint": "https://t"
        });
        assert!(
            !parse_as_metadata(&quiet, "https://as.example.com")
                .expect("valid")
                .iss_parameter_supported
        );

        let no_token = serde_json::json!({ "issuer": "https://i", "authorization_endpoint": "https://a" });
        assert!(parse_as_metadata(&no_token, "https://i").is_none());
    }

    /// F188: RFC 8414 §3.3. The metadata's `issuer` must be byte-identical to
    /// the issuer it was requested for; otherwise the RFC 9207 `iss` check
    /// compares the response against a value the document chose itself.
    #[test]
    fn as_metadata_must_name_the_issuer_it_was_requested_for() {
        let doc = |issuer: &str| {
            serde_json::json!({
                "issuer": issuer,
                "authorization_endpoint": "https://as.example.com/authorize",
                "token_endpoint": "https://as.example.com/token",
                "authorization_response_iss_parameter_supported": true
            })
        };
        let requested = "https://as.example.com";
        assert!(parse_as_metadata(&doc(requested), requested).is_some());
        // A third party's issuer, and every normalisation, is a mismatch.
        for claimed in [
            "https://third-party.example",
            "https://as.example.com/",
            "https://AS.example.com",
            "https://as.example.com:443",
        ] {
            assert!(
                parse_as_metadata(&doc(claimed), requested).is_none(),
                "{claimed} must not stand in for {requested}"
            );
        }
        // So the issuer recorded for the callback is the one the client asked
        // for, and a response naming the spoofed issuer is refused.
        let recorded = parse_as_metadata(&doc(requested), requested).expect("valid").issuer;
        assert_eq!(
            validate_issuer(&recorded, Some("https://third-party.example"), true),
            IssuerCheck::Reject("authorization response iss does not match the recorded issuer")
        );
    }

    /// F188: every endpoint in the metadata must be an `https://` URL.
    #[test]
    fn as_metadata_endpoints_must_be_https() {
        let with = |field: &str, value: &str| {
            let mut d = serde_json::json!({
                "issuer": "https://as.example.com",
                "authorization_endpoint": "https://as.example.com/authorize",
                "token_endpoint": "https://as.example.com/token",
                "registration_endpoint": "https://as.example.com/register"
            });
            d[field] = serde_json::json!(value);
            d
        };
        let issuer = "https://as.example.com";
        assert!(parse_as_metadata(&with("token_endpoint", "https://as.example.com/token"), issuer).is_some());
        for field in ["authorization_endpoint", "token_endpoint", "registration_endpoint"] {
            for bad in [
                "http://as.example.com/x",
                "javascript:alert(1)",
                "data:text/html,x",
                "https://user:pw@as.example.com/x",
                "https:///x",
                "/relative",
                "https://:443/x",
                "https://[broken/x",
                "https://as.example.com:bogus/x",
                "https://as.example.com:/x",
                "https://as.example.com/x#frag",
            ] {
                assert!(
                    parse_as_metadata(&with(field, bad), issuer).is_none(),
                    "{field} = {bad} must be refused"
                );
            }
        }
    }

    /// F485: an authorization endpoint with a fragment, or one that already
    /// names a parameter the client sends, is refused at parse time.
    #[test]
    fn as_metadata_refuses_an_authorization_endpoint_the_client_cannot_extend() {
        let with_endpoint = |endpoint: &str| {
            serde_json::json!({
                "issuer": "https://as.example.com",
                "authorization_endpoint": endpoint,
                "token_endpoint": "https://as.example.com/token"
            })
        };
        let issuer = "https://as.example.com";
        assert!(parse_as_metadata(&with_endpoint("https://as.example.com/auth?tenant=a"), issuer).is_some());
        for bad in [
            "https://as.example.com/auth#x",
            "https://as.example.com/auth?redirect_uri=https://evil.example",
            "https://as.example.com/auth?tenant=a&state=fixed",
            "https://as.example.com/auth?redirect%5Furi=x",
            "https://as.example.com/auth?scope",
        ] {
            assert!(parse_as_metadata(&with_endpoint(bad), issuer).is_none(), "{bad} must be refused");
        }
    }

    /// F485: even for hand-built metadata, the parameters land in the query
    /// (never inside a fragment) and none is sent twice.
    #[test]
    fn the_authorize_url_never_hides_parameters_in_a_fragment_or_repeats_one() {
        let mut meta = as_meta(false);
        meta.authorization_endpoint =
            "https://as.example.com/authorize?tenant=a&redirect_uri=https%3A%2F%2Fevil.example&state=fixed#frag"
                .into();
        let url = authorize_url(&AuthorizeRequest {
            metadata: &meta,
            client_id: "c",
            redirect_uri: "https://buzz.example/cb",
            scopes: &[],
            resource: "https://h.example/mcp",
            state: "st",
            code_challenge: "ch",
        });
        assert!(!url.contains('#'), "{url}");
        assert!(url.starts_with("https://as.example.com/authorize?tenant=a&response_type=code"), "{url}");
        assert_eq!(url.matches("redirect_uri=").count(), 1, "{url}");
        assert_eq!(url.matches("state=").count(), 1, "{url}");
        assert!(url.contains("redirect_uri=https%3A%2F%2Fbuzz.example%2Fcb"), "{url}");
        assert!(url.contains("&state=st"), "{url}");
        assert!(!url.contains("evil"), "{url}");
    }

    #[test]
    fn canonicalisation_folds_scheme_and_host_but_never_the_path() {
        // Paths are case-sensitive: /MCP is a DIFFERENT resource from /mcp, and
        // folding them would let a token for one be selected for the other.
        assert_eq!(
            canonical_resource("HTTPS://H.Example.COM/MCP").as_deref(),
            Some("https://h.example.com/MCP")
        );
        assert_eq!(
            canonical_resource("https://h.example.com/").as_deref(),
            Some("https://h.example.com")
        );
        // A fragment invalidates rather than being stripped.
        assert!(canonical_resource("https://h.example.com/mcp#frag").is_none());
        assert!(canonical_resource("h.example.com/mcp").is_none());
        assert!(canonical_resource("ftp://h.example.com").is_none());
    }

    #[test]
    fn only_the_host_is_folded_not_the_whole_authority() {
        // Userinfo is case-sensitive, so folding the authority would corrupt a
        // password. A resource identifier carrying credentials is refused instead:
        // credentials do not identify a resource.
        assert!(canonical_resource("https://user:PassWord@h.example.com/mcp").is_none());
        assert!(canonical_resource("https://user@h.example.com/mcp").is_none());

        // A port survives untouched, and the host beside it is still folded.
        assert_eq!(
            canonical_resource("https://H.Example.COM:8443/mcp").as_deref(),
            Some("https://h.example.com:8443/mcp")
        );
        // A non-numeric or empty port is malformed, not something to normalise.
        assert!(canonical_resource("https://h.example.com:port/mcp").is_none());
        assert!(canonical_resource("https://h.example.com:/mcp").is_none());
    }

    #[test]
    fn an_ipv6_literal_keeps_its_colons() {
        // Only a colon AFTER the closing bracket delimits a port.
        assert_eq!(
            canonical_resource("https://[2001:DB8::1]/mcp").as_deref(),
            Some("https://[2001:db8::1]/mcp")
        );
        assert_eq!(
            canonical_resource("https://[2001:db8::1]:8443/mcp").as_deref(),
            Some("https://[2001:db8::1]:8443/mcp")
        );
    }

    #[test]
    fn a_malformed_authority_is_refused_not_reinterpreted() {
        // Unbracketed IPv6. Previously parsed as host "2001:db8:" plus port "1",
        // which would give one address two spellings and so two credential keys.
        assert!(canonical_resource("https://2001:db8::1/mcp").is_none());
        // Unmatched opening bracket.
        assert!(canonical_resource("https://[2001:db8::1/mcp").is_none());
        // Junk after the closing bracket.
        assert!(canonical_resource("https://[::1]evil/mcp").is_none());
        // Empty brackets name no host.
        assert!(canonical_resource("https://[]/mcp").is_none());
        // A stray closing bracket with no opener.
        assert!(canonical_resource("https://h.example]/mcp").is_none());
        // Two colons with no brackets is not a host:port.
        assert!(canonical_resource("https://h.example:80:90/mcp").is_none());
    }

    #[test]
    fn a_derived_verifier_is_deterministic_and_connection_scoped() {
        // Deterministic: a redelivered request must reconstruct the SAME verifier,
        // or it orphans the authorization already in flight.
        let a = derive_verifier(SECRET, "conn-1", 0);
        assert_eq!(a, derive_verifier(SECRET, "conn-1", 0));
        assert_ne!(a, derive_verifier(SECRET, "conn-2", 0));
        // A deliberate re-authorization gets a fresh one.
        assert_ne!(a, derive_verifier(SECRET, "conn-1", 1));
        // The secret IS the security.
        assert_ne!(a, derive_verifier(b"other secret", "conn-1", 0));
        // base64url, unpadded, within the RFC 7636 length bounds.
        assert!(!a.contains('=') && !a.contains('+') && !a.contains('/'));
        assert!((43..=128).contains(&a.len()), "length {}", a.len());
    }

    #[test]
    fn state_and_verifier_never_collide() {
        // Same secret, connection and attempt: distinct labels keep them apart, so
        // the state cannot reveal the verifier.
        assert_ne!(
            derive_verifier(SECRET, "c", 0),
            derive_state(SECRET, "c", 0)
        );
    }

    #[test]
    fn the_challenge_is_s256_of_the_verifier() {
        // RFC 7636 appendix B.
        let verifier = "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk";
        assert_eq!(
            code_challenge(verifier),
            "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM"
        );
        assert_eq!(CODE_CHALLENGE_METHOD, "S256");
    }

    #[test]
    fn the_authorize_url_always_carries_resource_and_pkce() {
        let meta = as_meta(true);
        let scopes = vec!["mcp:read".to_string(), "mcp:write".to_string()];
        let url = authorize_url(&AuthorizeRequest {
            metadata: &meta,
            client_id: "https://buzz.example/cimd",
            redirect_uri: "https://buzz.example/buzz/api/mcp/callback",
            scopes: &scopes,
            resource: "https://h.example/mcp",
            state: "st",
            code_challenge: "ch",
        });
        assert!(url.starts_with("https://as.example.com/authorize?"));
        assert!(url.contains("response_type=code"));
        assert!(url.contains("code_challenge=ch"));
        assert!(url.contains("code_challenge_method=S256"));
        // RFC 8707, sent regardless of advertised support.
        assert!(
            url.contains("resource=https%3A%2F%2Fh.example%2Fmcp"),
            "{url}"
        );
        // Space-joined and encoded, never a raw space or a plus.
        assert!(url.contains("scope=mcp%3Aread%20mcp%3Awrite"), "{url}");
        assert!(!url.contains('+'));
    }

    #[test]
    fn an_endpoint_with_an_existing_query_gets_an_ampersand() {
        let mut meta = as_meta(false);
        meta.authorization_endpoint = "https://as.example.com/authorize?tenant=a".into();
        let url = authorize_url(&AuthorizeRequest {
            metadata: &meta,
            client_id: "c",
            redirect_uri: "r",
            scopes: &[],
            resource: "https://h.example/mcp",
            state: "s",
            code_challenge: "ch",
        });
        assert!(url.contains("?tenant=a&response_type=code"), "{url}");
        // No scopes means no parameter, rather than an empty one.
        assert!(!url.contains("scope="), "{url}");
    }

    #[test]
    fn a_hostile_state_cannot_forge_a_parameter() {
        let meta = as_meta(false);
        let url = authorize_url(&AuthorizeRequest {
            metadata: &meta,
            client_id: "c",
            redirect_uri: "r",
            scopes: &[],
            resource: "https://h.example/mcp",
            state: "x&redirect_uri=https://evil.example",
            code_challenge: "ch",
        });
        assert!(!url.contains("&redirect_uri=https://evil.example"), "{url}");
        assert!(url.contains("%26redirect_uri%3D"), "{url}");
    }

    #[test]
    fn the_challenge_wins_over_advertised_scopes() {
        let challenge = vec!["mcp:write".to_string()];
        let advertised = vec!["mcp:read".to_string()];
        assert_eq!(initial_scopes(&challenge, &advertised), challenge);
        assert_eq!(initial_scopes(&[], &advertised), advertised);
        assert!(initial_scopes(&[], &[]).is_empty());
    }

    #[test]
    fn a_step_up_unions_rather_than_replaces() {
        let had = vec!["mcp:read".to_string(), "mcp:tools".to_string()];
        let now = vec!["mcp:write".to_string(), "mcp:read".to_string()];
        // Everything previously granted survives; replacing would break the
        // operations that relied on it.
        assert_eq!(
            step_up_scopes(&had, &now),
            vec!["mcp:read", "mcp:tools", "mcp:write"]
        );
    }

    #[test]
    fn the_issuer_table_has_four_rows_and_all_four_are_implemented() {
        let recorded = "https://as.example.com";
        // advertised + present -> compare (match)
        assert_eq!(
            validate_issuer(recorded, Some(recorded), true),
            IssuerCheck::Ok
        );
        // advertised + absent -> REJECT
        assert!(matches!(
            validate_issuer(recorded, None, true),
            IssuerCheck::Reject(_)
        ));
        // not advertised + present -> compare anyway
        assert!(matches!(
            validate_issuer(recorded, Some("https://evil.example"), false),
            IssuerCheck::Reject(_)
        ));
        assert_eq!(
            validate_issuer(recorded, Some(recorded), false),
            IssuerCheck::Ok
        );
        // not advertised + absent -> proceed
        assert_eq!(validate_issuer(recorded, None, false), IssuerCheck::Ok);
    }

    #[test]
    fn issuer_comparison_does_no_uri_normalisation_whatsoever() {
        let recorded = "https://as.example.com";
        // Each of these is the SAME URI after normalisation, and each must still be
        // refused: normalising is exactly what enables the mix-up attack.
        for hostile in [
            "https://AS.example.com",
            "HTTPS://as.example.com",
            "https://as.example.com:443",
            "https://as.example.com/",
            "https://as.example%2Ecom",
        ] {
            assert!(
                matches!(
                    validate_issuer(recorded, Some(hostile), true),
                    IssuerCheck::Reject(_)
                ),
                "{hostile} must not compare equal to {recorded}"
            );
        }
    }

    #[test]
    fn the_token_request_carries_the_verifier_and_the_resource() {
        let form = token_request_form(
            "the-code",
            "https://buzz.example/cb",
            "client",
            "verifier",
            "https://h.example/mcp",
        );
        assert!(form.starts_with("grant_type=authorization_code"));
        assert!(form.contains("code=the-code"));
        assert!(form.contains("code_verifier=verifier"));
        assert!(
            form.contains("resource=https%3A%2F%2Fh.example%2Fmcp"),
            "{form}"
        );
    }

    #[test]
    fn a_refresh_also_names_the_resource() {
        // Without it, a refresh could be answered with a token for another audience.
        let form = refresh_request_form("rt", "client", "https://h.example/mcp");
        assert!(form.starts_with("grant_type=refresh_token"));
        assert!(
            form.contains("resource=https%3A%2F%2Fh.example%2Fmcp"),
            "{form}"
        );
    }

    #[test]
    fn a_token_response_must_state_a_bearer_token_type() {
        let good = serde_json::json!({
            "access_token": "at",
            "token_type": "Bearer",
            "expires_in": 3600,
            "refresh_token": "rt",
            "scope": "mcp:read mcp:write"
        });
        let g = parse_token_response(&good).expect("valid");
        assert_eq!(g.access_token, "at");
        assert_eq!(g.refresh_token.as_deref(), Some("rt"));
        assert_eq!(g.expires_in, Some(3600));
        assert_eq!(g.scope, vec!["mcp:read", "mcp:write"]);

        // OAuth 2.1 makes token_type REQUIRED. A token whose type was never
        // stated is one the client has not established how to use, and guessing
        // Bearer would be inventing the server's answer.
        assert!(parse_token_response(&serde_json::json!({ "access_token": "at" })).is_err());
        assert!(parse_token_response(&serde_json::json!({ "access_token": "at", "token_type": "" })).is_err());
        assert!(
            parse_token_response(&serde_json::json!({ "access_token": "at", "token_type": "MAC" })).is_err()
        );
        // Capitalisation of the type is not significant.
        assert!(
            parse_token_response(&serde_json::json!({ "access_token": "at", "token_type": "bearer" })).is_ok()
        );

        // But a response with no AUDIENCE is perfectly valid: audience binding came
        // from having sent `resource`, and the resource server enforces it.
        let no_audience = serde_json::json!({ "access_token": "at", "token_type": "Bearer" });
        assert!(parse_token_response(&no_audience).is_ok());

        assert!(parse_token_response(&serde_json::json!({})).is_err());
        assert!(
            parse_token_response(&serde_json::json!({ "access_token": "", "token_type": "Bearer" })).is_err()
        );
    }

    #[test]
    fn a_challenge_yields_the_scopes_and_the_metadata_url() {
        let header = "Bearer error=\"insufficient_scope\", error_description=\"needs write\", \
                      scope=\"mcp:read mcp:write\", \
                      resource_metadata=\"https://h.example/.well-known/oauth-protected-resource/mcp\"";
        let c = parse_challenge(header).expect("parses");
        assert!(c.is_insufficient_scope());
        assert_eq!(c.scope, vec!["mcp:read", "mcp:write"]);
        assert_eq!(
            c.resource_metadata.as_deref(),
            Some("https://h.example/.well-known/oauth-protected-resource/mcp")
        );
        assert_eq!(c.error_description.as_deref(), Some("needs write"));
    }

    #[test]
    fn a_comma_inside_a_quoted_value_does_not_split_the_challenge() {
        // Splitting naively truncates exactly the text a person needs on failure.
        let header = "Bearer error=\"invalid_token\", error_description=\"expired, please retry\"";
        let c = parse_challenge(header).expect("parses");
        assert_eq!(
            c.error_description.as_deref(),
            Some("expired, please retry")
        );
    }

    #[test]
    fn a_challenge_refuses_unsafe_metadata_urls_duplicates_and_unclosed_quotes() {
        // finding_934ba6d1d9aa69fc
        for url in [
            "http://169.254.169.254/latest/meta-data/",
            "file:///etc/passwd",
            "javascript:alert(1)",
        ] {
            let c = parse_challenge(&format!("Bearer resource_metadata=\"{url}\""))
                .expect("still a Bearer challenge");
            assert_eq!(c.resource_metadata, None, "{url} was kept");
        }
        assert!(parse_challenge("Bearer scope=\"a\", scope=\"b\"").is_none());
        assert!(parse_challenge(
            "Bearer resource_metadata=\"https://a.example/m\", resource_metadata=\"https://b.example/m\""
        )
        .is_none());
        assert!(parse_challenge("Bearer error=\"invalid_token").is_none());
        // An escaped quote stays inside its value.
        let c = parse_challenge("Bearer error_description=\"say \\\"hi\\\", ok\", error=x")
            .expect("parses");
        assert_eq!(c.error_description.as_deref(), Some("say \"hi\", ok"));
        assert_eq!(c.error.as_deref(), Some("x"));
    }

    #[test]
    fn challenge_parsing_tolerates_what_servers_actually_send() {
        // Bare values, odd spacing, unknown parameters.
        let c =
            parse_challenge("bearer  error=invalid_token ,  realm=x,  scope=a").expect("parses");
        assert_eq!(c.error.as_deref(), Some("invalid_token"));
        assert_eq!(c.scope, vec!["a"]);
        // A bare scheme with no parameters is still a Bearer challenge.
        assert_eq!(parse_challenge("Bearer"), Some(Challenge::default()));
        // A different scheme is not ours to interpret.
        assert!(parse_challenge("Basic realm=x").is_none());
    }

    #[test]
    fn canonical_resource_and_https_url_reject_backslashes_bad_hosts_ports_and_quotes() {
        for hostile in [
            "https://shared.example\\attacker-path/mcp",
            "https://attacker.example\\trusted.example/authorize",
            "https://bad$host.example/mcp",
            "https://[not-ipv6!]/mcp",
            "https://h.example:65536/mcp",
            "https://h.example:0/mcp",
            "https://h.example/mcp\" injected=1",
            "https://h.example/mcp with space",
            "https://h.example/mcp\r\nx: 1",
        ] {
            assert_eq!(
                canonical_resource(hostile),
                None,
                "hostile resource {hostile:?} must be refused by canonical_resource"
            );
            assert!(
                !is_https_url(hostile),
                "hostile URL {hostile:?} must be refused by is_https_url"
            );
        }
    }
}
